def evaluate(expr):
    # Evaluate respecting standard operator precedence (parse and reduce multiplications first).
    tokens = []
    num = ''
    sign = '+'
    for ch in expr + '+':
        if ch.isdigit():
            num += ch
        else:
            if sign == '+':
                tokens.append(int(num))
            elif sign == '-':
                tokens.append(-int(num))
            elif sign == '*':
                tokens.append(tokens.pop() * int(num))
            sign = ch
            num = ''
    return sum(tokens)

