def add_operators(num, target):
    result = []
    n = len(num)

    def backtrack(index, path, value, prev):
        if index == n:
            if value == target:
                result.append(path)
            return
        for i in range(index, n):
            if i > index and num[index] == '0':          # no leading zero for multi-digit numbers
                break
            cur_str = num[index:i+1]
            cur = int(cur_str)
            if index == 0:
                backtrack(i + 1, cur_str, cur, cur)         # first number, no operator
            else:
                backtrack(i + 1, path + '+' + cur_str, value + cur, cur)
                backtrack(i + 1, path + '-' + cur_str, value - cur, -cur)
                backtrack(i + 1, path + '*' + cur_str, value - prev + prev * cur, prev * cur)  # undo, reapply

    backtrack(0, '', 0, 0)
    return result

