import java.util.*;

public class Main {
    static List<String> result;
    static String num;
    static int n, target;

    static List<String> addOperators(String numStr, int targetVal) {
        result = new ArrayList<>();
        num = numStr; n = num.length(); target = targetVal;
        backtrack(0, "", 0L, 0L);
        return result;
    }

    static void backtrack(int index, String path, long value, long prev) {
        if (index == n) {
            if (value == target) result.add(path);
            return;
        }
        for (int i = index; i < n; i++) {
            if (i > index && num.charAt(index) == '0') break;      // no leading zero
            String curStr = num.substring(index, i + 1);
            long cur = Long.parseLong(curStr);
            if (index == 0) {
                backtrack(i + 1, curStr, cur, cur);
            } else {
                backtrack(i + 1, path + "+" + curStr, value + cur, cur);
                backtrack(i + 1, path + "-" + curStr, value - cur, -cur);
                backtrack(i + 1, path + "*" + curStr, value - prev + prev * cur, prev * cur);  // undo, reapply
            }
        }
    }
}

